src='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    # The repeated locator is the color occurring as isolated single cells,
    # while the stamp is the remaining non-background pattern.
    def components(color):
        seen=set(); comps=[]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen: continue
                stack=[(r,c)]; seen.add((r,c)); comp=[]
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny]==color and (nx,ny) not in seen:
                            seen.add((nx,ny)); stack.append((nx,ny))
                comps.append(comp)
        return comps
    isolated=[]
    for color in colors:
        cc=components(color)
        if len(cc)>1 and sum(map(len,cc))==len(cc): isolated.append((color,cc))
    marker, marker_comps=max(isolated, key=lambda x: len(x[1]))
    markers=[comp[0] for comp in marker_comps]
    stamp_colors=colors-{marker}
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c] in stamp_colors]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    stamp=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    ar=(r1-r0)//2; ac=(c1-c0)//2
    out=[row[:] for row in grid]
    for r,c in markers:
        for i,row in enumerate(stamp):
            for j,v in enumerate(row):
                rr=r+i-ar; cc=c+j-ac
                if 0<=rr<h and 0<=cc<w and v!=bg and v!=marker:
                    out[rr][cc]=v
    return out
'''
